from PIL import Image

bool = ""

im = Image.open(r"data\img\lol\items_full_alt.png")
size = 900

new_im = Image.new('RGBA', (48*size, 48))

x_offset = 0
for i in range(len(bool)):
    if bool[i] == "0": continue
    
    box = (i * 48, 0, (i + 1) * 48, 48)
    
    region = im.crop(box)
    new_im.paste(region, (x_offset*48, 0))
    x_offset += 1

new_im.save('./data/img/lol/items_full_alt_alt.png')